mapper.sql:
select e.endpoint_id as endpointId, e.data_source_id as dataSourceId, s.source_code as sourceCode, s.source_name as sourceName, e.endpoint_code as endpointCode, e.endpoint_name as endpointName, e.path, e.method, e.request_content_type as requestContentType, s.source_type as sourceType, s.status as sourceStatus, s.config_json as sourceConfigJson, s.secret_ciphertext as sourceSecretCiphertext, e.response_type as responseType, e.auth_provider as authProvider, e.credential_ref as credentialRef, e.config_json as configJson, e.credential_ciphertext as credentialCiphertext, e.contract_version as contractVersion, e.status, e.last_test_at as lastTestAt, e.last_test_status as lastTestStatus, e.last_request_id as lastRequestId, e.last_success_at as lastSuccessAt, e.consecutive_failures as consecutiveFailures, e.last_error_code as lastErrorCode, e.create_by as createBy, e.create_time as createTime, e.update_by as updateBy, e.update_time as updateTime, e.remark from dashboard_data_source_endpoint e join dashboard_data_source s on s.data_source_id = e.data_source_id where s.source_code = #{sourceCode}
and (e.endpoint_code like concat('%', #{keyword}, '%') or e.endpoint_name like concat('%', #{keyword}, '%'))
and e.status = #{status} order by e.endpoint_id desc

mapper.update:
update dashboard_data_source_endpoint
endpoint_name = #{endpointName}, path = #{path}, method = #{method}, request_content_type = #{requestContentType}, response_type = #{responseType}, auth_provider = #{authProvider}, credential_ref = #{credentialRef}, config_json = #{configJson}, credential_ciphertext = #{credentialCiphertext}, contract_version = #{contractVersion}, status = #{status}, remark = #{remark}, last_test_at = null, last_test_status = null, update_by = #{updateBy}, update_time = now()
where endpoint_id = #{endpointId}

update dashboard_data_source_endpoint
set last_test_status = #{status}, last_test_at = now()
where endpoint_id = #{endpointId}

update dashboard_data_source_endpoint
last_request_id = #{lastRequestId}, last_test_status = #{quality}, last_success_at = now(), consecutive_failures = 0, consecutive_failures = consecutive_failures + 1, last_error_code = #{errorCode}
where endpoint_id = #{endpointId}

mapper.sql:
select integration_id as integrationId, integration_code as integrationCode, integration_name as integrationName, environment, profile, folder_id as folderId, (select f.folder_name from dashboard_data_folder f where f.folder_id = i.folder_id and f.scope = 'integration') as folderName, schema_version as schemaVersion, endpoint_code as endpointCode, project_scope_json as projectScopeJson, config_json as configJson, network_profile as networkProfile, allowed_ip_json as allowedIpJson, timezone, max_batch_items as maxBatchItems, max_body_bytes as maxBodyBytes, rate_limit as rateLimit, concurrency_limit as concurrencyLimit, raw_retention_days as rawRetentionDays, status, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark, (select count(*) from dashboard_integration_key k where k.integration_id = i.integration_id) as keyCount, (select count(*) from dashboard_integration_key k where k.integration_id = i.integration_id and k.status = 'ACTIVE') as activeKeyCount from dashboard_integration i
and (integration_code like concat('%', #{keyword}, '%') or integration_name like concat('%', #{keyword}, '%'))
and environment = #{environment} and status = #{status}
and folder_id in #{id}
and 1 = 0
order by integration_id desc

mapper.update:
update dashboard_integration
integration_name = #{integrationName}, folder_id = #{folderId}, environment = #{environment}, profile = #{profile}, schema_version = #{schemaVersion}, endpoint_code = #{endpointCode}, project_scope_json = #{projectScopeJson}, config_json = #{configJson}, network_profile = #{networkProfile}, allowed_ip_json = #{allowedIpJson}, timezone = #{timezone}, max_batch_items = #{maxBatchItems}, max_body_bytes = #{maxBodyBytes}, rate_limit = #{rateLimit}, concurrency_limit = #{concurrencyLimit}, raw_retention_days = #{rawRetentionDays}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where integration_id = #{integrationId}

update dashboard_integration_batch
status = #{status}, accepted_count = #{acceptedCount}, processing_count = #{processingCount}, duplicate_count = #{duplicateCount}, rejected_count = #{rejectedCount}, retryable_count = #{retryableCount}, response_json = #{responseJson}, error_code = #{errorCode}, error_message = #{errorMessage}, processed_at = #{processedAt}, processed_at = null, processed_at = now(),
where batch_id = #{batchId}

update dashboard_integration_message
status = #{status}, retry_count = #{retryCount}, normalized_json = #{normalizedJson}, error_code = #{errorCode}, error_message = #{errorMessage}, processed_at = #{processedAt}, processed_at = null,
where integration_message_id = #{integrationMessageId}

update dashboard_integration_record
project_code = #{projectCode}, data_json = #{dataJson}, source_business_time = #{sourceBusinessTime}, source_updated_at = #{sourceUpdatedAt}, version_no = #{versionNo}, status = #{status}, updated_at = now()
where record_id = #{recordId}

mapper.select:
select batch_id as batchId, integration_id as integrationId, endpoint_code as endpointCode, normalized_idempotency_key as normalizedIdempotencyKey, message_id as messageId, external_request_id as externalRequestId, body_hash as bodyHash, platform_request_id as platformRequestId, schema_version as schemaVersion, status, accepted_count as acceptedCount, processing_count as processingCount, duplicate_count as duplicateCount, rejected_count as rejectedCount, retryable_count as retryableCount, error_code as errorCode, error_message as errorMessage, received_at as receivedAt, processed_at as processedAt, details_expired_at as detailsExpiredAt from dashboard_integration_batch
and integration_id = #{integrationId} and status = #{status}
order by batch_id desc limit #{limit}

select m.integration_message_id as integrationMessageId, m.batch_id as batchId, m.integration_id as integrationId, i.integration_code as integrationCode, m.profile, m.business_key as businessKey, m.item_index as itemIndex, m.project_code as projectCode, m.status, m.retry_count as retryCount, m.error_code as errorCode, m.error_message as errorMessage, m.received_at as receivedAt, m.processed_at as processedAt from dashboard_integration_message m join dashboard_integration i on i.integration_id = m.integration_id where m.status = 'DEAD_LETTER' and m.integration_id = #{integrationId}
and (m.business_key like concat('%', #{keyword}, '%') or m.error_code like concat('%', #{keyword}, '%'))
order by m.integration_message_id desc limit #{limit}

mapper.update:
update dashboard_integration_media_ref set status = 'REVOKED'
where page_id = #{pageId}
and revision_id = #{revisionId}
and share_id is null
and status = 'ACTIVE'
